/**
 * 复制图片到剪贴板。
 *
 * 只接收现成的 PNG Blob：页面里的图是 canvas 渲染出来的，如果等到点击时才 fetch(dataURL)
 * 再写剪贴板，中间这段异步会让浏览器认为「用户手势已经结束」，剪贴板写入会被拒绝。
 * 所以两张图的 Blob 在生成时就存好，点击时直接写。
 *
 * 浏览器不支持图片剪贴板（或页面不在安全上下文，比如 http 而非 https/localhost）时抛错，
 * 由调用方提示用户改用下载。
 *
 * @param {Blob} blob PNG 二进制
 */
export async function copyImageToClipboard(blob) {
  if (!blob) throw new Error('图片还没生成好')
  if (!navigator.clipboard || !window.ClipboardItem) throw new Error('浏览器不支持复制图片')
  await navigator.clipboard.write([new ClipboardItem({ 'image/png': blob })])
}
