<template>
  <!-- 猜曲游戏的两个玩法切换：放在参数栏「曲目」下面，选完曲就能直接换玩法 -->
  <div class="gm-tabs">
    <button
      v-for="item in MODES"
      :key="item.value"
      class="gm-tab"
      :class="{ 'gm-tab--on': modelValue === item.value }"
      @click="pick(item.value)"
    >
      {{ item.label }}
    </button>
  </div>
</template>

<script setup>
const props = defineProps({
  modelValue: { type: String, default: 'lian' },
})

const emit = defineEmits(['update:modelValue'])

const MODES = [
  { value: 'kai', label: '开字母' },
  { value: 'lian', label: '连字谜' },
]

function pick(value) {
  if (value !== props.modelValue) emit('update:modelValue', value)
}
</script>

