<template>
  <div class="gp-root">
    <div class="gp-main">
      <!-- 左：参数栏。玩法见 useKaiLetters.js，这里只管排版；外壳样式在 gamePanel.css -->
      <aside class="gp-side dt-panel">
        <section class="gp-sec">
          <h3 class="gp-sec-title">曲目</h3>
          <song-selects @selected-change="onSongsSelected" />
          <div class="gp-line">
            <span>已选曲目</span>
            <output class="dt-num">{{ songList.length }} 首</output>
          </div>
        </section>

        <!-- 玩法切换：选完曲就在这切到连字谜 -->
        <game-modes :model-value="mode" @update:model-value="emit('update:mode', $event)" />

        <!-- 生成与下载：按钮排布和连字谜一致 -->
        <section class="gp-sec">
          <button
            class="dt-btn dt-btn--primary gp-btn-full"
            :disabled="!songList.length"
            @click="restart"
          >
            生成题目
          </button>
          <div class="gp-pair">
            <button class="dt-btn gp-btn-full" :disabled="!rows.length" @click="copyQuestionText">
              复制题目文本
            </button>
            <button class="dt-btn gp-btn-full" :disabled="!rows.length" @click="copyAnswerText">
              复制答案文本
            </button>
          </div>
          <div class="gp-pair">
            <button class="dt-btn gp-btn-full" :disabled="!questionImageUrl" @click="copyQuestionImage">
              复制题目图片
            </button>
            <button class="dt-btn gp-btn-full" :disabled="!answerImageUrl" @click="copyAnswerImage">
              复制答案图片
            </button>
          </div>
          <div class="gp-switches">
            <button
              type="button"
              class="switch"
              :class="{ 'switch--on': showAnswer }"
              role="switch"
              :aria-checked="showAnswer"
              @click="showAnswer = !showAnswer"
            >
              <span class="switch__dot"></span>
              <span>显示答案</span>
            </button>
          </div>
          <!-- 复制等操作的结果放在这里；答题结果的提示在「开」按钮下面 -->
          <p v-if="note" class="gp-msg" :class="`gp-msg--${noteTone || 'info'}`">{{ note }}</p>
        </section>

        <section class="gp-sec">
          <h3 class="gp-sec-title">出题规则</h3>
          <div class="gp-line">
            <span>抽取数量</span>
            <output class="dt-num">{{ pickCount }} 首</output>
          </div>
          <div class="stepper">
            <button type="button" class="stepper__btn" aria-label="抽取数量减一" @click="bumpPick(-1)">−</button>
            <input
              v-model.number="pickCount"
              class="num-input dt-num"
              type="number"
              min="1"
              :max="maxRows"
              aria-label="抽取数量"
              @change="onPickChange"
            />
            <button type="button" class="stepper__btn" aria-label="抽取数量加一" @click="bumpPick(1)">+</button>
          </div>

          <!-- 出题规则并入本段，省掉一个只有开关的分区标题 -->
          <div class="gp-switches gp-switches--inset">
            <button
              type="button"
              class="switch"
              :class="{ 'switch--on': keepSpaces }"
              role="switch"
              :aria-checked="keepSpaces"
              title="保留曲名里的空格"
              @click="keepSpaces = !keepSpaces"
            >
              <span class="switch__dot"></span>
              <span>保留空格</span>
            </button>
          </div>
        </section>

        <section class="gp-sec">
          <h3 class="gp-sec-title">开字母</h3>
          <!-- 遮蔽字符：左边标签、右边输入框，和「抽取数量」那行同高 -->
          <div class="kai-mask-row">
            <span class="kai-mask-row__label">遮蔽字符</span>
            <input
              v-model="maskChar"
              class="dt-field dt-num kai-field kai-mask-row__input"
              type="text"
              maxlength="1"
              aria-label="遮蔽字符"
              @change="normalizeMask"
            />
          </div>

          <input
            ref="inputRef"
            v-model="input"
            class="dt-field kai-field"
            type="text"
            placeholder="字符 / 完整曲名"
            @keyup.enter="onSubmit"
          />
          <button class="dt-btn dt-btn--primary gp-btn-full" @click="onSubmit">开</button>
          <p v-if="message" class="gp-msg" :class="`gp-msg--${messageTone || 'info'}`">{{ message }}</p>
        </section>

        <section class="gp-sec">
          <h3 class="gp-sec-title">进度</h3>
          <div class="gp-line">
            <span>猜出</span>
            <output class="dt-num">{{ solvedRows }} / {{ totalRows }}</output>
          </div>
          <div class="gp-line">
            <span>未揭开</span>
            <output class="dt-num">{{ hiddenCount }}</output>
          </div>
        </section>
      </aside>

      <!-- 右：题板 -->
      <section class="gp-stage kai-stage">
        <div class="kai-boards">
          <section class="gp-board kai-board">
          <header class="board__head">
            <span class="board__title">题目</span>
            <span class="board__meta dt-num">猜出 {{ solvedRows }} / {{ totalRows }} · 未揭开 {{ hiddenCount }}</span>
          </header>

          <div class="board__viewport kai-viewport">
            <div v-if="!rows.length" class="board__empty">选好曲目后点「生成题目」</div>
            <template v-else>
              <div class="kai-list">
                <div
                  v-for="(row, index) in rows"
                  :key="row.id"
                  class="kai-row"
                  :class="{ 'kai-row--done': row.solved }"
                >
                  <span class="kai-no dt-num">{{ index + 1 }}</span>
                  <span class="kai-name">
                    <template v-for="(c, i) in row.chars" :key="i">
                      <span v-if="c.gap" class="kai-gap"></span>
                      <span
                        v-else
                        class="kai-char"
                        :class="{ 'kai-char--on': c.revealed }"
                      >{{ c.revealed ? c.ch : maskChar }}</span>
                    </template>
                  </span>
                  <span v-if="row.solved" class="kai-done">✓</span>
                </div>
              </div>

              <div v-if="finished" class="kai-finish">全部猜出</div>
            </template>
          </div>

          <!-- 已经开出过哪些字母 -->
          <footer class="kai-opened">
            <span class="kai-opened__label">已开出</span>
            <span v-for="ch in openedChars" :key="ch" class="dt-chip">{{ ch }}</span>
            <span v-if="!openedChars.length" class="kai-opened__empty">还没有开过字母</span>
          </footer>
        </section>

        <!-- 答案单独一块板，由「显示答案」开关控制 -->
        <section v-if="showAnswer" class="gp-board kai-board">
          <header class="board__head">
            <span class="board__title">答案</span>
            <span class="board__meta dt-num">共 {{ totalRows }} 首</span>
          </header>
          <div class="board__viewport kai-viewport">
            <div v-if="!rows.length" class="board__empty">选好曲目后点「生成题目」</div>
            <div v-else class="kai-list">
              <div v-for="(row, index) in rows" :key="row.id" class="kai-row">
                <span class="kai-no dt-num">{{ index + 1 }}</span>
                <span class="kai-name kai-name--answer">{{ row.name }}</span>
                <span v-if="row.solved" class="kai-done">✓</span>
              </div>
            </div>
          </div>
          </section>
        </div>
      </section>
    </div>

    <!-- 离屏导出容器：题目（按当前遮蔽状态）/ 答案（全开），导出时渲染成 PNG -->
    <div ref="questionWrapRef" class="image-wrap-hidden">
      <div class="kai-export">
        <div v-for="(row, index) in rows" :key="row.id" class="kai-export__row">
          <span class="kai-export__no">{{ index + 1 }}</span>
          <span
            v-for="(c, i) in row.chars"
            :key="i"
            class="kai-export__cell"
            :class="{ 'kai-export__cell--gap': c.gap }"
          >{{ c.gap ? '' : (c.revealed ? c.ch : maskChar) }}</span>
        </div>
      </div>
    </div>

    <div ref="answerWrapRef" class="image-wrap-hidden">
      <div class="kai-export">
        <div v-for="(row, index) in rows" :key="row.id" class="kai-export__row">
          <span class="kai-export__no">{{ index + 1 }}</span>
          <span
            v-for="(c, i) in row.chars"
            :key="i"
            class="kai-export__cell"
            :class="{ 'kai-export__cell--gap': c.gap }"
          >{{ c.gap ? '' : c.ch }}</span>
        </div>
      </div>
    </div>
  </div>
</template>

<script setup>
import { ref, nextTick } from 'vue'
import songSelects from '../ui/songSelects.vue'
import gameModes from './gameModes.vue'
import { useKaiLetters } from './useKaiLetters.js'

// 玩法切换由父页面持有，本组件只负责把选中值转出去
defineProps({
  mode: { type: String, default: 'kai' },
})

const emit = defineEmits(['update:mode'])

const {
  songList,
  onSongsSelected,
  rows,
  pickCount,
  maskChar,
  keepSpaces,
  showAnswer,
  normalizeMask,
  input,
  message,
  messageTone,
  note,
  noteTone,
  hiddenCount,
  totalRows,
  solvedRows,
  openedChars,
  finished,
  clampInt,
  restart,
  bumpPick,
  submit,
  questionWrapRef,
  answerWrapRef,
  questionImageUrl,
  answerImageUrl,
  copyQuestionText,
  copyAnswerText,
  copyQuestionImage,
  copyAnswerImage,
  maxRows,
} = useKaiLetters()




const inputRef = ref(null)

function onSubmit() {
  submit()
  // 回车后把焦点留在输入框，连着猜不用每次点一下
  nextTick(() => inputRef.value && inputRef.value.focus())
}

/* 抽取数量：只夹到合法区间，不重开题目（重开交给「重新抽取」/「生成题目」） */
function onPickChange() {
  pickCount.value = clampInt(pickCount.value, 1, maxRows, 5)
}
</script>

