<template>
  <div class="gp-root">
    <div class="gp-main">
      <aside class="gp-side dt-panel">
        <section class="gp-sec">
          <h3 class="gp-sec-title">曲目</h3>
          <song-selects @selected-change="onSongsSelected" />
          <div class="gp-line">
            <span>已选曲目</span>
            <output class="dt-num">{{ songList.length }} 首</output>
          </div>
        </section>

        <!-- 玩法切换：选完曲就在这切到开字母 -->
        <game-modes :model-value="mode" @update:model-value="emit('update:mode', $event)" />

        <section class="gp-sec">
          <button
            class="dt-btn dt-btn--primary gp-btn-full"
            :disabled="isGenerating || !songList.length"
            @click="generatePuzzle"
          >
            {{ isGenerating ? '生成中…' : '生成题目' }}
          </button>
          <div class="gp-pair">
            <button class="dt-btn gp-btn-full" :disabled="!questionImageUrl" @click="copyQuestionImage">
              复制题目图片
            </button>
            <button class="dt-btn gp-btn-full" :disabled="!answerImageUrl" @click="copyAnswerImage">
              复制答案图片
            </button>
          </div>
          <div class="gp-pair">
            <button class="dt-btn gp-btn-full" :disabled="!questionImageUrl" @click="downloadQuestionImage">
              下载题目图片
            </button>
            <button class="dt-btn gp-btn-full" :disabled="!answerImageUrl" @click="downloadAnswerImage">
              下载答案图片
            </button>
          </div>
          <div class="gp-switches">
            <button
              type="button"
              class="switch"
              :class="{ 'switch--on': showAnswer }"
              role="switch"
              :aria-checked="showAnswer"
              @click="showAnswer = !showAnswer"
            >
              <span class="switch__dot"></span>
              <span>显示答案</span>
            </button>
          </div>
          <!-- 复制/下载的结果放在这里，和开字母的参数栏排布保持一致 -->
          <p v-if="notice" class="gp-msg" :class="`gp-msg--${noticeTone || 'info'}`">{{ notice }}</p>
        </section>

        <section class="gp-sec">
