          <div class="gp-line">
            <span>网格大小</span>
            <output class="dt-num">{{ gridCols }} × {{ gridRows }}</output>
          </div>
          <div class="gp-pair">
            <div class="stepper">
              <button type="button" class="stepper__btn" aria-label="列数减一" @click="bumpValue('tempGridCols', -1, 10, 64)">−</button>
              <input
                v-model.number="tempGridCols"
                class="num-input dt-num"
                type="number"
                min="10"
                max="64"
                aria-label="网格列数"
                @change="tempGridCols = clampInt(tempGridCols, 10, 64)"
              />
              <button type="button" class="stepper__btn" aria-label="列数加一" @click="bumpValue('tempGridCols', 1, 10, 64)">+</button>
            </div>
            <span class="gp-sep">×</span>
            <div class="stepper">
              <button type="button" class="stepper__btn" aria-label="行数减一" @click="bumpValue('tempGridRows', -1, 10, 64)">−</button>
              <input
                v-model.number="tempGridRows"
                class="num-input dt-num"
                type="number"
                min="10"
                max="64"
                aria-label="网格行数"
                @change="tempGridRows = clampInt(tempGridRows, 10, 64)"
              />
              <button type="button" class="stepper__btn" aria-label="行数加一" @click="bumpValue('tempGridRows', 1, 10, 64)">+</button>
            </div>
          </div>

          <div class="gp-line">
            <span>选曲数量</span>
            <output class="dt-num">{{ gameSongCount }} 首</output>
          </div>
          <div class="stepper">
            <button type="button" class="stepper__btn" aria-label="选曲数量减一" @click="bumpValue('gameSongCount', -1, 1, 256)">−</button>
            <input
              v-model.number="gameSongCount"
              class="num-input dt-num"
              type="number"
              min="1"
              max="256"
              aria-label="选曲数量"
              @change="gameSongCount = clampInt(gameSongCount, 1, 256, 5)"
