        <section class="gp-sec">
          <h3 class="gp-sec-title">进度</h3>
          <div class="gp-line">
            <span>已找到</span>
            <output class="dt-num">{{ foundCount }} / {{ totalWords }}</output>
          </div>
          <div class="gp-line">
            <span>剩余</span>
            <output class="dt-num">{{ Math.max(totalWords - foundCount, 0) }}</output>
          </div>
          <p v-if="allFound && totalWords" class="gp-msg gp-msg--ok">全部找到了</p>
        </section>
      </aside>

