              <div
                v-for="(cell, idx) in gridList"
                :key="idx"
                class="cell"
                :class="{ 'cell--sel': cellMarks[idx] && cellMarks[idx].end }"
                :style="cellMarks[idx] && cellMarks[idx].background ? { background: cellMarks[idx].background, color: cellMarks[idx].color } : null"
                @mousedown="onCellDown(idx, $event)"
                @mouseenter="onCellEnter(idx)"
              >
                {{ cell.letter }}
              </div>
            </div>
            <div v-if="!gridList.length" class="board__empty">先选曲目，再点「生成题目」</div>
