    <div ref="questionWrapRef" class="image-wrap-hidden">
      <div class="grid-image-container">
        <div class="grid-image" :style="{ gridTemplateColumns: `repeat(${gridCols}, 1fr)` }">
          <div
            v-for="(cell, idx) in gridList"
            :key="idx"
            class="cell-image"
            style="background:rgba(255,255,255,0.08);"
          >
            {{ cell.letter }}
          </div>
        </div>
      </div>
    </div>

    <!-- 答案截图容器 -->
    <div ref="answerWrapRef" class="image-wrap-hidden">
      <div class="grid-image-container">
        <div class="grid-image" :style="{ gridTemplateColumns: `repeat(${gridCols}, 1fr)` }">
          <div
            v-for="(cell, idx) in answerGridList"
            :key="idx"
            class="cell-image"
            :style="{ background: cell.color }"
          >
            {{ cell.letter }}
          </div>
        </div>
      </div>
    </div>
  </div>
</template>

<script setup>
import songSelects from '../ui/songSelects.vue'
import gameModes from './gameModes.vue'
import { useLianWordGame } from './useLianWordGame.js'

// 玩法切换由父页面（猜曲游戏页）持有，本组件只把选中值转出去
defineProps({
  mode: { type: String, default: 'lian' },
})

const emit = defineEmits(['update:mode'])

/* 玩法逻辑都在 useLianWordGame.js（出题、放字、导图），这里只解出模板用到的名字 */
const {
  songList,
  onSongsSelected,
  generatePuzzle,
  isGenerating,
  copyQuestionImage,
  copyAnswerImage,
  downloadQuestionImage,
  downloadAnswerImage,
  questionImageUrl,
  answerImageUrl,
  questionWrapRef,
  answerWrapRef,
  gridCols,
  gridRows,
  tempGridCols,
  tempGridRows,
  clampInt,
  bumpValue,
  gameSongCount,
  allowNonEnglish,
  ignoreCase,
  showAnswer,
  notice,
  noticeTone,
  gridList,
  answerGridList,
  placements,
  foundCount,
  totalWords,
  allFound,
  cellMarks,
  onCellDown,
  onCellEnter,
  onGridUp,
  cellFontSize,
  handleMouseDown,
  handleMouseMove,
  handleMouseUp,
} = useLianWordGame()


</script>

