/**
 * 连字谜的玩法逻辑：出题、放字、生成题目 / 答案图片。
 *
 * 从 lianWordGame.vue 里拆出来，模板只负责排版与双向绑定；
 * 这里不含任何样式，也不认识 .gp-* 类名。
 */
import { ref, computed, watch, nextTick, onBeforeUnmount } from 'vue'
import html2canvas from 'html2canvas'
import { exportFileName } from '../../utils/exportName.js'
import { copyImageToClipboard } from '../../utils/clipboard.js'

/* 只沿右下三个方向放字：这样每首词的格子不会互相覆盖得太厉害 */
const directions = [
  [0, 1],
  [1, 0],
  [1, 1]
]

/* 答案里标记每首词用的底色（半透明，压在格子上不挡字） */
const COLORS = [
  'rgba(59, 130, 246, 0.25)',
  'rgba(16, 185, 129, 0.25)',
  'rgba(245, 158, 11, 0.25)',
  'rgba(239, 68, 68, 0.25)',
  'rgba(168, 85, 247, 0.25)',
  'rgba(217, 70, 239, 0.25)',
  'rgba(237, 137, 54, 0.25)',
  'rgba(82, 183, 136, 0.25)',
  'rgba(21, 122, 112, 0.25)',
  'rgba(79, 70, 229, 0.25)',
  'rgba(236, 72, 153, 0.25)',
  'rgba(234, 88, 12, 0.25)',
  'rgba(217, 119, 6, 0.25)',
  'rgba(132, 204, 22, 0.25)',
  'rgba(14, 165, 233, 0.25)',
  'rgba(99, 102, 241, 0.25)',
  'rgba(249, 115, 22, 0.25)',
  'rgba(251, 191, 36, 0.25)',
  'rgba(134, 239, 172, 0.25)',
  'rgba(125, 211, 252, 0.25)',
  'rgba(196, 181, 253, 0.25)',
  'rgba(241, 156, 186, 0.25)',
  'rgba(127, 29, 29, 0.25)',
  'rgba(46, 125, 50, 0.25)',
  'rgba(26, 35, 126, 0.25)',
  'rgba(121, 40, 113, 0.25)'
]

export function useLianWordGame() {
  // 曲目由面板里的「选曲列表」弹窗提供：songSelects 挂载后会把默认选中的曲目 emit 上来
  const songList = ref([])

  /* 面板里输入的行列数（temp*）与真正生效的（grid*）分开：
     输入框允许暂时是超范围的值，点「生成字谜」时才夹紧并使用 */
  const tempGridCols = ref(10)
  const tempGridRows = ref(10)
  const gridCols = ref(10)
  const gridRows = ref(10)
  const gameSongCount = ref(5)
  const allowNonEnglish = ref(false)
  const ignoreCase = ref(false)

  const grid = ref([])
  const gridList = ref([])
  const placements = ref([])
  const gameSongs = ref([])
  const songCharSet = ref(new Set())
  const answerGridList = ref([])

  // 连线玩法：found 存已找到的曲目在 placements 里的下标；selStart/selEnd 是当前选中的两格下标
  const found = ref([])
  const selStart = ref(-1)
  const selEnd = ref(-1)
  const dragging = ref(false)

  // 判错时把连着的那串格子闪几下再清掉：不扣分、不记进度
  const flashCells = ref([])
  const flashOn = ref(false)
  let flashTimer = null
  let flashTicks = 0

  function stopFlash() {
    if (flashTimer) {
      window.clearInterval(flashTimer)
      flashTimer = null
    }
    flashCells.value = []
    flashOn.value = false
  }

  function startFlash(cells) {
    stopFlash()
    flashCells.value = [...cells]
    flashOn.value = true
    flashTicks = 0
    // 亮灭交替 6 次（约半秒）后自动清掉
    flashTimer = window.setInterval(() => {
      flashTicks += 1
      flashOn.value = !flashOn.value
      if (flashTicks >= 6) stopFlash()
    }, 80)
  }

  const isGenerating = ref(false)

  const showAnswer = ref(false) // 舞台上的「答案」棋板是否显示（默认收起）
  const notice = ref('')
  const noticeTone = ref('')
  const questionImageUrl = ref('')
  const answerImageUrl = ref('')
  // 出图时顺手存下 PNG Blob，复制图片时直接用，避免点击后再异步取图丢掉用户手势
  const questionImageBlob = ref(null)
  const answerImageBlob = ref(null)

  /* 两块棋板的滚动容器（拖动平移用） */
  const gridRef = ref(null)
  const questionWrapRef = ref(null)
  const answerWrapRef = ref(null)

  const isDragging = ref(false)
  const dragEl = ref(null)
  const startX = ref(0)
  const startY = ref(0)
  const scrollLeft = ref(0)
  const scrollTop = ref(0)

  function onSongsSelected(data) {
    songList.value = data.selectedSongs
  }

  // 输入框失焦 / 回车时才夹紧数值：边输入边改写会让「50」这种两位数根本打不进去，
  // 同时也兜住手输超范围（例如直接输 999）导致生成超大网格把页面卡死的情况
  function clampInt(value, min, max, fallback = min) {
    const n = Math.round(Number(value))
    if (!Number.isFinite(n)) return fallback
    return Math.min(max, Math.max(min, n))
  }

  // 单元格字号跟着列数走：10 列时 0.16rem（约格子宽的三成），列数越多字越小，免得撑破格子
  const cellFontSize = computed(() => {
    const cols = Math.max(1, Number(gridCols.value) || 1)
    return `${Math.min(0.16, Math.max(0.045, 1.6 / cols))}rem`
  })

  // 数字框两侧的加减按钮：原生 spinner 在缩放后的窄框里会把数字挤掉，所以自己画一对。
  // 字段用名字传（字符串）：模板里传 ref 拿到的是解包后的数字，对它取 .value 会报错
  const STEPPER_FIELDS = { tempGridCols, tempGridRows, gameSongCount }

  function bumpValue(key, delta, min, max) {
    const field = STEPPER_FIELDS[key]
    if (!field) return
    field.value = clampInt(Number(field.value) + delta, min, max, min)
  }

  function handleMouseDown(e) {
    isDragging.value = true
    dragEl.value = e.currentTarget
    startX.value = e.pageX
    startY.value = e.pageY
    scrollLeft.value = e.currentTarget.scrollLeft
    scrollTop.value = e.currentTarget.scrollTop
    e.preventDefault()
  }

  function handleMouseMove(e) {
    // 只让「按下时的那一块」跟着拖动，避免拖过中线时题目和答案一起跳（光标样式由 CSS 的 :active 负责）
    if (!isDragging.value || e.currentTarget !== dragEl.value) return
    const dx = e.pageX - startX.value
    const dy = e.pageY - startY.value
    e.currentTarget.scrollLeft = scrollLeft.value - dx
    e.currentTarget.scrollTop = scrollTop.value - dy
  }

  function handleMouseUp() {
    isDragging.value = false
    dragEl.value = null
  }

  function cleanName(name) {
    if (!name) return ''
    let res = name

    if (!allowNonEnglish.value) {
      res = res.replace(/[^a-zA-Z0-9]/g, '')
    }
    else {
      res = res.replace(/\s/g, '')
    }

    if (ignoreCase.value) res = res.toUpperCase()
    return res.trim()
  }

  function getValidSongs(list) {
    const maxLen = Math.min(gridCols.value, gridRows.value) - 1
    const res = []
    list.forEach(item => {
      const clean = cleanName(item.name)
      if (clean && clean.length >= 2 && clean.length <= maxLen) {
        res.push({ raw: item, clean })
      }
    })
    return res
  }

  function pickSongs(validList, count) {
    const shuffled = [...validList].sort(() => Math.random() - 0.5)
    return shuffled.slice(0, Math.min(count, validList.length))
  }

  /* 反复试放 100 轮，取「放进去的词最多」的一版；剩空格用已选曲目的字母随机填满 */
  function generateFullGrid(words) {
    let bestGrid = []
    let bestPlacements = []
    let bestCount = 0
    const targetCount = words.length

    for (let attempt = 0; attempt < 100; attempt++) {
      const g = Array(gridRows.value).fill().map(() => Array(gridCols.value).fill(''))
      const placed = []

      words.forEach(word => {
        const w = word.clean
        const len = w.length
        let placedOne = false

        for (let i = 0; i < 50; i++) {
          const r = Math.floor(Math.random() * gridRows.value)
          const c = Math.floor(Math.random() * gridCols.value)
          const [dr, dc] = directions[Math.floor(Math.random() * directions.length)]
          const er = r + dr * (len - 1)
          const ec = c + dc * (len - 1)
          if (er >= gridRows.value || ec >= gridCols.value) continue

          let ok = true
          for (let j = 0; j < len; j++) {
            const nr = r + dr * j
            const nc = c + dc * j
            if (g[nr][nc] && g[nr][nc] !== w[j]) { ok = false; break }
          }
          if (ok) {
            for (let j = 0; j < len; j++) {
              const nr = r + dr * j
              const nc = c + dc * j
              g[nr][nc] = w[j]
            }
            placed.push({ word: w, r, c, dr, dc })
            placedOne = true
            break
          }
        }
        return placedOne
      })

      if (placed.length > bestCount) {
        bestCount = placed.length
        bestGrid = JSON.parse(JSON.stringify(g))
        bestPlacements = [...placed]
      }

      if (bestCount === targetCount) break
    }

    const chars = Array.from(songCharSet.value)

    for (let i = 0; i < gridRows.value; i++) {
      for (let j = 0; j < gridCols.value; j++) {
        if (!bestGrid[i][j]) {
          bestGrid[i][j] = chars[Math.floor(Math.random() * chars.length)]
        }
      }
    }

    return { grid: bestGrid, placements: bestPlacements }
  }

  /* 答案：把每首词所占格子的底色换成一个专属颜色，其余保持透明 */
  function renderAnswerGrid(placementsList) {
    const list = []
    for (let i = 0; i < gridRows.value; i++) {
      for (let j = 0; j < gridCols.value; j++) {
        list.push({ letter: grid.value[i][j], color: 'transparent' })
      }
    }

    placementsList.forEach((p, index) => {
      const color = COLORS[index % COLORS.length]
      const { r, c, dr, dc, word } = p
      for (let k = 0; k < word.length; k++) {
        const nr = r + dr * k
        const nc = c + dc * k
        const idx = nr * gridCols.value + nc
        if (list[idx]) {
          list[idx].color = color
        }
      }
    })

    answerGridList.value = list
  }

  async function initGame(list) {
    if (!list || !list.length) return

    gridCols.value = clampInt(tempGridCols.value, 10, 64)
    gridRows.value = clampInt(tempGridRows.value, 10, 64)

    grid.value = []
    gridList.value = []
    placements.value = []
    gameSongs.value = []
    songCharSet.value.clear()
    questionImageUrl.value = ''
    answerImageUrl.value = ''
    questionImageBlob.value = null
    answerImageBlob.value = null
    notice.value = ''
    found.value = []
    stopFlash()
    cancelSelection()

    const validList = getValidSongs(list)
    const selected = pickSongs(validList, clampInt(gameSongCount.value, 1, 256, 5))

    selected.forEach(s => {
      for (const c of s.clean) songCharSet.value.add(c)
    })

    const { grid: g, placements: p } = generateFullGrid(selected)
    grid.value = g
    placements.value = p
    gameSongs.value = selected

    flattenGrid()
    renderAnswerGrid(p)

    await createAllImages()
  }

  function flattenGrid() {
    const list = []
    for (let i = 0; i < gridRows.value; i++) {
      for (let j = 0; j < gridCols.value; j++) {
        list.push({ letter: grid.value[i][j] })
      }
    }
    gridList.value = list
  }

  /* 已找到多少首 / 一共几首：舞台标题上的进度 */
  const totalWords = computed(() => placements.value.length)
  const foundCount = computed(() => found.value.length)
  const allFound = computed(() => totalWords.value > 0 && foundCount.value === totalWords.value)

  /* 当前选择覆盖的格子下标：只认横、竖、斜三条方向，其它角度不合法 */
  const selectionCells = computed(() => {
    const s = selStart.value
    const e = selEnd.value
    if (s < 0 || e < 0) return []
    const cols = gridCols.value
    const sr = Math.floor(s / cols)
    const sc = s % cols
    const er = Math.floor(e / cols)
    const ec = e % cols
    const dr = er - sr
    const dc = ec - sc
    if (dr !== 0 && dc !== 0 && Math.abs(dr) !== Math.abs(dc)) return []
    const steps = Math.max(Math.abs(dr), Math.abs(dc))
    const stepR = Math.sign(dr)
    const stepC = Math.sign(dc)
    const list = []
    for (let k = 0; k <= steps; k++) list.push((sr + stepR * k) * cols + (sc + stepC * k))
    return list
  })

  /* 每格的颜色：已找到的用答案板同一套色；正在连的线两端深、中段浅；判错时整串闪红 */
  const cellMarks = computed(() => {
    const cols = gridCols.value
    const sel = selectionCells.value
    // 起点单独记住：还没连成合法直线（或连歪了）时也要把它染出来
    const start = selStart.value
    const ends = new Set()
    if (sel.length >= 2) {
      ends.add(sel[0])
      ends.add(sel[sel.length - 1])
    }
    if (start >= 0) ends.add(start)
    const tinted = new Set(sel)
    if (start >= 0) tinted.add(start)
    const marks = gridList.value.map((_, index) => ({ background: '', color: '', end: ends.has(index) }))
    const solved = new Set()
    found.value.forEach(index => {
      const p = placements.value[index]
      if (!p) return
      const color = COLORS[index % COLORS.length]
      for (let k = 0; k < p.word.length; k++) {
        const cell = (p.r + p.dr * k) * cols + (p.c + p.dc * k)
        if (!marks[cell]) continue
        marks[cell].background = color
        marks[cell].color = 'var(--dt-text)'
        solved.add(cell)
      }
    })
    tinted.forEach(index => {
      const mark = marks[index]
      if (!mark || mark.background) return
      mark.background = ends.has(index) ? 'rgba(122, 170, 255, 0.42)' : 'rgba(122, 170, 255, 0.18)'
      mark.color = ends.has(index) ? 'var(--dt-text)' : 'var(--dt-text-soft)'
    })
    if (flashOn.value) {
      flashCells.value.forEach(index => {
        const mark = marks[index]
        if (!mark || solved.has(index)) return
        mark.background = 'rgba(244, 63, 94, 0.45)'
        mark.color = 'var(--dt-text)'
      })
    }
    return marks
  })

  /* 点第一格开始选，点第二格或松开鼠标时判定 */
  function onCellDown(index, event) {
    // 只有左键选格子；其它键留给画布平移，大网格可以中键拖动
    if (event && event.button !== 0) return
    if (event) event.stopPropagation()
    if (selStart.value < 0) {
      selStart.value = index
      selEnd.value = index
      dragging.value = true
      return
    }
    selEnd.value = index
    commitSelection()
  }

  function onCellEnter(index) {
    if (selStart.value >= 0 && dragging.value) selEnd.value = index
  }

  function onGridUp() {
    if (!dragging.value) return
    dragging.value = false
    if (selStart.value !== selEnd.value) commitSelection()
    else cancelSelection()
  }

  function cancelSelection() {
    selStart.value = -1
    selEnd.value = -1
    dragging.value = false
  }

  /* 判定：连到的字串与某首曲目一致（且没找过）就算找到 */
  function commitSelection() {
    const cells = selectionCells.value
    const start = selStart.value
    const end = selEnd.value
    cancelSelection()
    if (cells.length < 2 || start < 0 || end < 0) return
    const text = cells.map(cell => gridList.value[cell]?.letter || '').join('').toLowerCase()
    if (!text) return
    const hit = placements.value.findIndex(p => p.word.toLowerCase() === text)
    if (hit >= 0) {
      // 连对：保持染色并计入进度（同一首重复连不重复计数）
      if (!found.value.includes(hit)) found.value = [...found.value, hit]
      return
    }
    // 连错：让这串格子闪几下，然后自己清掉
    startFlash(cells)
  }

  // 离开页面时清掉判错的闪动定时器，避免卸载后还在跑
  onBeforeUnmount(stopFlash)

  /* 两块棋板离屏渲染成 PNG（导出的两张图），页面里看不到这个容器 */
  async function createAllImages() {
    await nextTick()
    if (questionWrapRef.value) {
      const canvas1 = await html2canvas(questionWrapRef.value, { useCORS: true, scale: 2, backgroundColor: '#494949' })
      questionImageUrl.value = canvas1.toDataURL('image/png')
      questionImageBlob.value = await toPngBlob(canvas1)
    }
    if (answerWrapRef.value) {
      const canvas2 = await html2canvas(answerWrapRef.value, { useCORS: true, scale: 2, backgroundColor: '#494949' })
      answerImageUrl.value = canvas2.toDataURL('image/png')
      answerImageBlob.value = await toPngBlob(canvas2)
    }
  }

  /* canvas → PNG Blob（复制图片要现成的 Blob，不能等点击时才异步取图） */
  function toPngBlob(canvas) {
    return new Promise(resolve => canvas.toBlob(blob => resolve(blob), "image/png"))
  }

  async function generatePuzzle() {
    if (isGenerating.value) return
    isGenerating.value = true
    try {
      await initGame(songList.value)
    } finally {
      isGenerating.value = false
    }
  }

  /* 下载图片：直接触发浏览器另存为 PNG */
  function downloadImage(url, extra) {
    if (!url) return
    const a = document.createElement('a')
    a.download = exportFileName('猜曲游戏', extra, 'png')
    a.href = url
    a.click()
  }

  /* 复制图片：只写 image/png；不支持时提示改用下载，不再悄悄触发下载 */
  async function copyImage(blob, label) {
    if (!blob) {
      notice.value = '图片还没生成好，稍等一下再试。'
      noticeTone.value = 'bad'
      return
    }
    try {
      await copyImageToClipboard(blob)
      notice.value = ''
    found.value = []
    cancelSelection()
      noticeTone.value = ''
    }
    catch (err) {
      notice.value = `浏览器不支持复制图片，请改用「下载${label}图片」。`
      noticeTone.value = 'bad'
    }
  }

  function copyQuestionImage() {
    copyImage(questionImageBlob.value, '题目')
  }

  function copyAnswerImage() {
    copyImage(answerImageBlob.value, '答案')
  }

  function downloadQuestionImage() {
    downloadImage(questionImageUrl.value, ['题目'])
  }

  function downloadAnswerImage() {
    downloadImage(answerImageUrl.value, ['答案'])
  }

  // 选曲变化（含弹窗确认）就重开一局，省得手动再点生成
  watch(songList, val => initGame(val), { deep: true })

  return {
    songList,
    onSongsSelected,
    generatePuzzle,
    isGenerating,
    copyQuestionImage,
    copyAnswerImage,
    downloadQuestionImage,
    downloadAnswerImage,
    showAnswer,
    notice,
    noticeTone,
    questionImageUrl,
    answerImageUrl,
    questionWrapRef,
    answerWrapRef,
    gridRef,
    gridCols,
    gridRows,
    tempGridCols,
    tempGridRows,
    clampInt,
    bumpValue,
    gameSongCount,
    allowNonEnglish,
    ignoreCase,
    gridList,
    answerGridList,
    placements,
    found,
    foundCount,
    totalWords,
    allFound,
    cellMarks,
    onCellDown,
    onCellEnter,
    onGridUp,
    gameSongs,
    cellFontSize,
    handleMouseDown,
    handleMouseMove,
    handleMouseUp
  }
}
