/**
 * 开字母（猜曲游戏第二模式）的玩法逻辑。
 *
 * 规则：
 *   - 从选好的曲目里随机抽 N 首，除空格外的字符全部遮成「*」。
 *   - 输入一个字符：把各题里出现的这个字符一起揭开（区分大小写）。
 *   - 输入完整曲名：命中哪首就把哪首整行揭开。
 *   - 不计分、不计时；全部猜出即结束。
 */
import { ref, computed, watch, nextTick } from 'vue'
import html2canvas from 'html2canvas'
import { copyImageToClipboard } from '../../utils/clipboard.js'

/* 一题最多抽多少首：太多会挤满舞台，也失去「一起猜」的乐趣 */
const MAX_ROWS = 12

function normalize(text) {
  return String(text ?? '').replace(/\s+/g, '').toLowerCase()
}

export function useKaiLetters() {
  const songList = ref([])

  const rows = ref([])          // 每题：{ id, name, chars: [{ ch, revealed, gap }], solved }
  const pickCount = ref(5)      // 一次抽几首
  const maskChar = ref('*')     // 未揭开的字符显示成什么
  const keepSpaces = ref(true)  // 曲名里的空格是留成空隙还是压紧
  const showAnswer = ref(false) // 题板上直接露出真字符（做题时不开）
  const openedChars = ref([])   // 已经开出的字符（按开出顺序，区分大小写、不重复）
  const input = ref('')
  const message = ref('')      // 答题结果，显示在「开」按钮下面
  const messageTone = ref('')   // '' | 'ok' | 'bad'
  const note = ref('')         // 复制等操作的提示，显示在「显示答案」下面
  const noteTone = ref('')     // '' | 'ok' | 'bad'

  // 离屏导出：题目（带遮蔽）/ 答案（全开）两个容器，页面上看不见
  const questionWrapRef = ref(null)
  const answerWrapRef = ref(null)
  const questionImageUrl = ref('')
  const answerImageUrl = ref('')
  // 出图时顺手存下 PNG Blob，复制图片时直接用，避免点击后再异步取图丢掉用户手势
  const questionImageBlob = ref(null)
  const answerImageBlob = ref(null)

  const totalRows = computed(() => rows.value.length)
  const solvedRows = computed(() => rows.value.filter(row => row.solved).length)
  const finished = computed(() => totalRows.value > 0 && solvedRows.value === totalRows.value)
  // 还没揭开的字符总数：作为进度提示
  const hiddenCount = computed(() => {
    let n = 0
    for (const row of rows.value) {
      for (const c of row.chars) {
        if (!c.gap && !c.revealed) n++
      }
    }
    return n
  })

  function say(text, tone = '') {
    message.value = text
    messageTone.value = tone
  }

  function sayNote(text, tone = '') {
    note.value = text
    noteTone.value = tone
  }

  function clampInt(value, min, max, fallback = min) {
    const n = Math.round(Number(value))
    if (!Number.isFinite(n)) return fallback
    return Math.min(max, Math.max(min, n))
  }

  /* 抽题：打乱后取前 N 首，只保留有名字的（曲名全空白没法出题） */
  function buildRows(list) {
    const pool = (list || []).filter(item => normalize(item.name))
    for (let i = pool.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1))
      ;[pool[i], pool[j]] = [pool[j], pool[i]]
    }
    const picked = pool.slice(0, clampInt(pickCount.value, 1, MAX_ROWS, 5))
    return picked.map(item => ({
      id: item.id,
      name: item.name,
      solved: false,
      // keepSpaces 关掉时直接把空白字符去掉；空格永远不算「未揭开」
      chars: Array.from(String(item.name))
        .filter(ch => keepSpaces.value || !/\s/.test(ch))
        .map(ch => ({
          ch,
          gap: /\s/.test(ch),
          revealed: /\s/.test(ch),
        })),
    }))
  }

  async function startRound() {
    rows.value = buildRows(songList.value)
    openedChars.value = []
    input.value = ''
    questionImageUrl.value = ''
    answerImageUrl.value = ''
    questionImageBlob.value = null
    answerImageBlob.value = null
    // 开新一局时不提示用法，只有开字 / 猜题的结果才显示消息
    say('')
    sayNote('')

    await createAllImages()
  }

  /* 抽完题把两张导出图在离屏容器里渲染成 PNG（页面上看不到这两个容器） */
  async function createAllImages() {
    await nextTick()
    if (questionWrapRef.value) {
      const canvas = await html2canvas(questionWrapRef.value, { useCORS: true, scale: 2, backgroundColor: '#494949' })
      questionImageUrl.value = canvas.toDataURL('image/png')
      questionImageBlob.value = await toPngBlob(canvas)
    }
    if (answerWrapRef.value) {
      const canvas = await html2canvas(answerWrapRef.value, { useCORS: true, scale: 2, backgroundColor: '#494949' })
      answerImageUrl.value = canvas.toDataURL('image/png')
      answerImageBlob.value = await toPngBlob(canvas)
    }
  }

  /* canvas → PNG Blob（复制图片要现成的 Blob，不能等点击时才异步取图） */
  function toPngBlob(canvas) {
    return new Promise(resolve => canvas.toBlob(blob => resolve(blob), 'image/png'))
  }

  /* 复制纯文字：只写 text/plain，粘到任何输入框都是文字 */
  async function copyText(text) {
    try {
      await navigator.clipboard.writeText(text())
    }
    catch (err) {
      sayNote('浏览器不允许写剪贴板，请确认页面是 https 且已允许剪贴板权限。', 'bad')
    }
  }

  /* 复制图片：只写 image/png，粘到聊天框、文档里就是一张图 */
  async function copyImage(blob) {
    try {
      await copyImageToClipboard(blob)
    }
    catch (err) {
      sayNote('复制图片失败，浏览器可能不支持图片剪贴板。', 'bad')
    }
  }

  /* 题目板的纯文字形态：行号 + 当前遮蔽状态，末尾附上已开出的字符 */
  function questionText() {
    const lines = rows.value.map((row, index) => `${index + 1}. ${row.chars.map(c => (c.gap ? ' ' : c.revealed ? c.ch : maskChar.value)).join('')}`)
    const opened = openedChars.value.length ? ['', '已开出：', openedChars.value.join(',')] : []
    return [...lines, ...opened].join('\n')
  }

  /* 答案板的纯文字形态：只有曲名 */
  function answerText() {
    return rows.value.map((row, index) => `${index + 1}. ${row.name}`).join('\n')
  }

  function copyQuestionText() {
    copyText(questionText())
  }

  function copyAnswerText() {
    copyText(answerText())
  }

  function copyQuestionImage() {
    copyImage(questionImageBlob.value)
  }

  function copyAnswerImage() {
    copyImage(answerImageBlob.value)
  }

  function onSongsSelected(data) {
    songList.value = data.selectedSongs || []
  }

  function revealChar(char) {
    char.revealed = true
  }

  /* 输入一个字符：把所有题里同样的字符一起揭开（区分大小写）；
     不管这个字符在不在题目里，都记进「已开出」；
     某一行因此被全部揭开时直接算猜出——单字曲目点一次就中 */
  function guessChar(ch) {
    const solved = []
    for (const row of rows.value) {
      if (row.solved) continue
      for (const c of row.chars) {
        if (!c.gap && !c.revealed && c.ch === ch) revealChar(c)
      }
      if (row.chars.every(c => c.gap || c.revealed)) {
        row.solved = true
        solved.push(row.name)
      }
    }
    if (!openedChars.value.includes(ch)) openedChars.value.push(ch)
    if (solved.length) say(`猜对了：${solved.join('、')}`, 'ok')

    checkFinished()
  }

  /* 猜出整首：把该行全部揭开 */
  function solveRow(row) {
    for (const c of row.chars) c.revealed = true
    row.solved = true
    say(`猜对了：${row.name}`, 'ok')
  }

  function findRowByText(text) {
    const key = normalize(text)
    return rows.value.find(row => !row.solved && normalize(row.name) === key)
  }

  function checkFinished() {
    if (finished.value) say('全部猜出', 'ok')
  }

  function submit() {
    const raw = input.value.trim()
    input.value = ''
    if (!raw || !rows.value.length) return

    const chars = Array.from(raw)
    if (chars.length === 1) {
      guessChar(chars[0])
      return
    }

    const row = findRowByText(raw)
    if (row) {
      solveRow(row)
      checkFinished()
      return
    }
    say(`没有名为「${raw}」的曲目`, 'bad')
  }

  /* 抽取数量的加减按钮与手输都用同一套夹值逻辑：只改数字，重抽交给「重新抽取」 */
  function bumpPick(delta) {
    pickCount.value = clampInt(pickCount.value + delta, 1, MAX_ROWS, 5)
  }

  function onPickChange() {
    pickCount.value = clampInt(pickCount.value, 1, MAX_ROWS, 5)
  }

  /* 遮蔽字符只留一个字符，清空时退回「*」 */
  function normalizeMask() {
    const first = Array.from(String(maskChar.value ?? ''))[0]
    maskChar.value = first && first.trim() ? first : '*'
  }

  function restart() {
    startRound()
  }

  // 换选曲就重开一局：和连字谜保持一致
  watch(songList, () => startRound(), { deep: true })

  return {
    songList,
    onSongsSelected,
    rows,
    pickCount,
    maskChar,
    keepSpaces,
    showAnswer,
    normalizeMask,
    openedChars,
    input,
    message,
    messageTone,
    note,
    noteTone,
    hiddenCount,
    totalRows,
    solvedRows,
    finished,
    clampInt,
    onPickChange,
    bumpPick,
    restart,
    submit,
    questionWrapRef,
    answerWrapRef,
    questionImageUrl,
    answerImageUrl,
    copyQuestionText,
    copyAnswerText,
    copyQuestionImage,
    copyAnswerImage,
    maxRows: MAX_ROWS,
  }
}
